// Check if system is active and not emergency-stopped
const configRows = $input.all().map(i => i.json);

const getConfig = (key) => {
  const row = configRows.find(r => r.config_key === key);
  return row ? row.config_value : null;
};

const systemStatus = getConfig('system_status');
const emergencyStop = getConfig('emergency_stop');
const maxConcurrent = parseInt(getConfig('max_concurrent_runs') || '3');
const dailyBudgetLimit = parseFloat(getConfig('daily_budget_limit') || '50');
const dailyBudgetUsed = parseFloat(getConfig('daily_budget_used') || '0');

const isActive = systemStatus === 'active' && emergencyStop !== 'true';
const budgetAvailable = dailyBudgetUsed < dailyBudgetLimit;

if (!isActive) {
  console.log(`System not active. Status: ${systemStatus}, Emergency: ${emergencyStop}`);
}
if (!budgetAvailable) {
  console.log(`Daily budget exhausted: $${dailyBudgetUsed}/$${dailyBudgetLimit}`);
}

return [{
  json: {
    system_active: isActive && budgetAvailable,
    system_status: systemStatus,
    emergency_stop: emergencyStop,
    max_concurrent: maxConcurrent,
    daily_budget_limit: dailyBudgetLimit,
    daily_budget_used: dailyBudgetUsed,
    budget_remaining: dailyBudgetLimit - dailyBudgetUsed,
    checked_at: new Date().toISOString()
  }
}];

// Determine which channels need content today
// C-Optimized schedule:
//   Month 1-2: 1 Long + 7 Shorts/week (daily short, 1 long on schedule day)
//   Month 3+:  2 Longs + 3 Shorts/week
// For now we use the Channel_DNA values for videos_per_week_long/short

const channels = $('Read Channel_DNA').all().map(i => i.json);
const locks = $('Read Execution_Locks').all().map(i => i.json);

function getISOWeek(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

function getISOWeekString(d) {
  return `${d.getFullYear()}-W${String(getISOWeek(d)).padStart(2, '0')}`;
}

const now = new Date();
const today = now.toISOString().split('T')[0];
const dayOfWeek = now.getDay(); // 0=Sun, 1=Mon, ...
const currentWeek = getISOWeekString(now);

const activeChannels = channels.filter(ch => ch.status === 'active');
const tasksToDispatch = [];

for (const ch of activeChannels) {
  const channelId = ch.channel_id;

  // Check locks for this channel this week
  const weekLocks = locks.filter(l =>
    l.channel_id === channelId &&
    l.execution_week === currentWeek &&
    l.status === 'completed'
  );

  const shortsThisWeek = weekLocks.filter(l => l.run_id && l.run_id.includes('short')).length;
  const longsThisWeek = weekLocks.filter(l => l.run_id && l.run_id.includes('long')).length;

  const maxShorts = parseInt(ch.videos_per_week_short) || 7;
  const maxLongs = parseInt(ch.videos_per_week_long) || 1;

  // Check if already ran today
  const ranToday = weekLocks.some(l => l.locked_at && l.locked_at.startsWith(today));
  if (ranToday) continue;

  // Determine what to produce
  // Shorts: produce daily if under weekly limit
  if (shortsThisWeek < maxShorts) {
    tasksToDispatch.push({
      channel_id: channelId,
      channel_name: ch.channel_name,
      niche: ch.niche,
      sub_niche: ch.sub_niche,
      content_mode: 'short',
      execution_week: currentWeek,
      run_id: `${channelId}_short_${today}`,
      brand_voice: ch.brand_voice,
      narrative_rhythm: ch.narrative_rhythm,
      emotional_contract: ch.emotional_contract,
      intellectual_lens: ch.intellectual_lens,
      belief_territory: ch.belief_territory,
      topic_domain: ch.topic_domain,
      target_word_count: parseInt(ch.words_per_video_short) || 80,
      max_script_words: parseInt(ch.max_script_words_short) || 90,
      min_script_words: parseInt(ch.min_script_words_short) || 70,
      elevenlabs_voice_id: ch.elevenlabs_voice_id,
      primary_color: ch.primary_color,
      secondary_color: ch.secondary_color,
      font_family: ch.font_family,
      caption_style: ch.caption_style,
      pacing_style: ch.pacing_style,
      thumbnail_style: ch.thumbnail_style,
      forbidden_words: ch.forbidden_words,
      target_audience: ch.target_audience,
      video_template: ch.video_template,
      visual_only_ratio: parseFloat(ch.visual_only_ratio) || 0.12,
      hook_length_seconds: parseInt(ch.hook_length_seconds_short) || 2,
      today: today
    });
  }

  // Longs: produce on specific days (spread across week)
  // For 1 long/week: produce on Monday (dayOfWeek=1)
  // For 2 longs/week: produce on Monday and Thursday
  const longDays = maxLongs === 1 ? [1] : maxLongs === 2 ? [1, 4] : [1, 3, 5];

  if (longDays.includes(dayOfWeek) && longsThisWeek < maxLongs) {
    tasksToDispatch.push({
      channel_id: channelId,
      channel_name: ch.channel_name,
      niche: ch.niche,
      sub_niche: ch.sub_niche,
      content_mode: 'long',
      execution_week: currentWeek,
      run_id: `${channelId}_long_${today}`,
      brand_voice: ch.brand_voice,
      narrative_rhythm: ch.narrative_rhythm,
      emotional_contract: ch.emotional_contract,
      intellectual_lens: ch.intellectual_lens,
      belief_territory: ch.belief_territory,
      topic_domain: ch.topic_domain,
      target_word_count: parseInt(ch.words_per_video_long) || 1100,
      max_script_words: parseInt(ch.max_script_words_long) || 1200,
      min_script_words: parseInt(ch.min_script_words_long) || 1000,
      elevenlabs_voice_id: ch.elevenlabs_voice_id,
      primary_color: ch.primary_color,
      secondary_color: ch.secondary_color,
      font_family: ch.font_family,
      caption_style: ch.caption_style,
      pacing_style: ch.pacing_style,
      thumbnail_style: ch.thumbnail_style,
      forbidden_words: ch.forbidden_words,
      target_audience: ch.target_audience,
      video_template: ch.video_template,
      visual_only_ratio: parseFloat(ch.visual_only_ratio) || 0.12,
      hook_length_seconds: parseInt(ch.hook_length_seconds_long) || 8,
      today: today
    });
  }
}

console.log(`Dispatching ${tasksToDispatch.length} tasks for ${activeChannels.length} active channels`);

if (tasksToDispatch.length === 0) {
  return [{ json: { no_tasks: true, reason: 'All channels up to date for today', checked_at: new Date().toISOString() } }];
}

return tasksToDispatch.map(t => ({ json: t }));

// Select a belief and topic, avoiding recent ones
const task = $('Process One at a Time').item.json;
const beliefs = $('Read Beliefs for Channel').all().map(i => i.json);
const recentVideos = $('Read Recent Videos').all().map(i => i.json);

// Get last 10 topics used by this channel
const recentTopics = recentVideos
  .slice(-10)
  .map(v => (v.assigned_topic || '').toLowerCase())
  .filter(t => t);

// Get last 5 beliefs used
const recentBeliefIds = recentVideos
  .slice(-5)
  .map(v => v.belief_id || '')
  .filter(b => b);

// Filter available beliefs (not recently used, not cooling)
const now = new Date();
const availableBeliefs = beliefs.filter(b => {
  if (b.belief_status === 'exhausted') return false;
  if (recentBeliefIds.includes(b.belief_id)) return false;
  if (b.cooling_until_date && new Date(b.cooling_until_date) > now) return false;
  return true;
});

// Select belief (prefer least used)
let selectedBelief = null;
if (availableBeliefs.length > 0) {
  availableBeliefs.sort((a, b) => (parseInt(a.times_used) || 0) - (parseInt(b.times_used) || 0));
  selectedBelief = availableBeliefs[0];
} else if (beliefs.length > 0) {
  // Fallback: use any belief
  selectedBelief = beliefs[Math.floor(Math.random() * beliefs.length)];
}

// Build the payload for Workflow B1
const payload = {
  // Task identity
  channel_id: task.channel_id,
  channel_name: task.channel_name,
  content_mode: task.content_mode,
  execution_week: task.execution_week,
  run_id: task.run_id,
  dispatched_at: new Date().toISOString(),

  // Channel DNA
  niche: task.niche,
  sub_niche: task.sub_niche,
  brand_voice: task.brand_voice,
  narrative_rhythm: task.narrative_rhythm,
  emotional_contract: task.emotional_contract,
  intellectual_lens: task.intellectual_lens,
  topic_domain: task.topic_domain,
  target_audience: task.target_audience,
  forbidden_words: task.forbidden_words,

  // Content specs
  target_word_count: task.target_word_count,
  max_script_words: task.max_script_words,
  min_script_words: task.min_script_words,
  hook_length_seconds: task.hook_length_seconds,
  visual_only_ratio: task.visual_only_ratio,

  // Visual identity
  elevenlabs_voice_id: task.elevenlabs_voice_id,
  primary_color: task.primary_color,
  secondary_color: task.secondary_color,
  font_family: task.font_family,
  caption_style: task.caption_style,
  pacing_style: task.pacing_style,
  thumbnail_style: task.thumbnail_style,
  video_template: task.video_template,

  // Selected belief
  belief_id: selectedBelief ? selectedBelief.belief_id : '',
  belief: selectedBelief ? selectedBelief.belief : '',
  counter_narrative: selectedBelief ? selectedBelief.counter_narrative : '',
  angle: selectedBelief ? selectedBelief.angle : '',

  // Dedup context
  recent_topics: recentTopics.join(', '),
  total_videos_published: recentVideos.length
};

console.log(`Dispatching ${task.content_mode} for ${task.channel_name} | Belief: ${payload.belief || 'none'}`);

return [{ json: payload }];

// Log completion and loop back to batch processor
const task = $('Process One at a Time').item.json;
console.log(`✅ Dispatched: ${task.channel_name} (${task.content_mode}) — ${task.run_id}`);
return [{ json: { dispatched: true, run_id: task.run_id, channel_id: task.channel_id } }];
